    return { i, ref: String(r[CFG.col_ref]).trim(), placedRaw: r[CFG.col_placed], placed, stamp, stampRaw: r[CFG.col_updated], amountRaw: r[CFG.col_amount], cents, currency, note: r[CFG.col_note] };
