export default ({ table }) => {
  const RATE = { EUR: 10898, GBP: 12639, USD: 10000 };
  const CUTOVER = '2025-10-22';
  const pad = n => String(n).padStart(2, '0');
  const isoDate = s => {
    const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(s).trim());
    if (!m) return null;
    const d = Number(m[1]), mo = Number(m[2]), y = Number(m[3]);
    const dt = new Date(Date.UTC(y, mo - 1, d));
    if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) return null;
    return `${y}-${pad(mo)}-${pad(d)}`;
  };
  const changeKey = s => {
    const m = /^(\d{2})\/(\d{2})\/(\d{4}) (\d{2}):(\d{2})$/.exec(String(s).trim());
    if (!m) throw new Error('bad LastChange: ' + s);
    return `${m[3]}-${m[2]}-${m[1]} ${m[4]}:${m[5]}`;
  };
  const rows = table.rows.map(r => {
    const cur = (r.Currency || '').trim() || 'EUR';
    if (!Object.prototype.hasOwnProperty.call(RATE, cur)) throw new Error('unknown currency: ' + cur);
    const amt = String(r.Total).trim().replace(/O/g, '0');
    if (!/^\d+(\.\d{1,2})?$/.test(amt)) throw new Error('bad amount: ' + r.Total);
    const [w, f = ''] = amt.split('.');
    const cents = Number(w) * 100 + Number((f + '00').slice(0, 2));
    return {
      ref: r.OrderNo.trim(),
      key: changeKey(r.LastChange),
      currency: cur,
      note: r['Status Note'],
      placed: isoDate(r.DATE_PLACED),
      usd_cents: Math.floor((cents * RATE[cur] + 5000) / 10000)
    };
  });
  const current = new Map();
  for (const r of rows) {
    const old = current.get(r.ref);
    if (!old || r.key > old.key) current.set(r.ref, r);
  }
  const quarantine = [], candidates = [];
  const sorted = [...current.values()].sort((a, b) => (a.ref < b.ref ? -1 : a.ref > b.ref ? 1 : 0));
  for (const r of sorted) {
    if (r.placed === null) { quarantine.push(r.ref); continue; }
    if (r.placed > CUTOVER) continue;
    candidates.push({ ref: r.ref, placed: r.placed, currency: r.currency, usd_cents: r.usd_cents, note: r.note });
  }
  return { quarantine, candidates };
};

export default ({ judged, quarantine, channel }) => {
  const LABELS = ['awaiting_intake', 'awaiting_customer', 'dispatched', 'cancelled'];
  for (const r of judged) {
    if (!LABELS.includes(r.status)) throw new Error('bad status for ' + r.ref + ': ' + r.status);
  }
  const imp = judged
    .filter(r => r.status !== 'cancelled')
    .sort((a, b) => (a.ref < b.ref ? -1 : a.ref > b.ref ? 1 : 0))
    .map(r => ({ ref: r.ref, placed: r.placed, status: r.status, usd_cents: r.usd_cents }));
  const sum = imp.reduce((s, r) => s + r.usd_cents, 0);
  return {
    channel,
    import: imp,
    quarantine: [...quarantine].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)),
    totals: { orders: imp.length, usd_cents: sum }
  };
};

export default ({ result, table }) => {
  const problems = [];
  const refs = new Set(table.rows.map(r => r.OrderNo.trim()));
  const imp = result.import;
  if (result.totals.orders !== imp.length) problems.push('order count mismatch');
  const s = imp.reduce((a, r) => a + r.usd_cents, 0);
  if (result.totals.usd_cents !== s) problems.push('sum mismatch');
  const q = new Set(result.quarantine);
  const seen = new Set();
  for (const r of imp) {
    if (!refs.has(r.ref)) problems.push('unknown ref ' + r.ref);
    if (seen.has(r.ref)) problems.push('duplicate ' + r.ref);
    seen.add(r.ref);
    if (q.has(r.ref)) problems.push('imported and quarantined ' + r.ref);
    if (r.status === 'cancelled') problems.push('cancelled imported ' + r.ref);
    if (r.placed > '2025-10-22') problems.push('placed after cutover ' + r.ref);
  }
  return problems.length ? { ok: false, problems } : true;
};

