export default ({ table }) => {
  const CUTOVER = '2025-07-26';
  const RATE = { EUR: 11050, GBP: 12839, USD: 10000 };
  const realDate = (s) => {
    const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(s).trim());
    if (!m) return null;
    const d = +m[1], mo = +m[2], y = +m[3];
    const dt = new Date(Date.UTC(y, mo - 1, d));
    if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) return null;
    return `${m[3]}-${m[2]}-${m[1]}`;
  };
  const stamp = (s) => {
    const m = /^(\d{2})\/(\d{2})\/(\d{4}) (\d{2}):(\d{2})$/.exec(String(s).trim());
    if (!m) throw new Error('bad UPDATED_AT: ' + s);
    return Number(m[3] + m[2] + m[1] + m[4] + m[5]);
  };
  const cents = (s) => {
    const t = String(s).trim().replace(/O/g, '0').replace(/\./g, '').replace(',', '.');
    if (!/^\d+(\.\d{1,2})?$/.test(t)) throw new Error('bad amount: ' + s);
    return Math.round(parseFloat(t) * 100);
  };
  const curOf = (s) => {
    const c = String(s).trim() || 'EUR';
    if (!(c in RATE)) throw new Error('bad currency: ' + c);
    return c;
  };
  const rows = table.rows;
  const sums = { EUR: 0, GBP: 0, USD: 0 };
  for (const r of rows) sums[curOf(r.Curr)] += cents(r['Order Value']);
  const trailer = table.comments.find(l => l.startsWith('#END')) || '';
  const tr = {};
  for (const m of trailer.matchAll(/(EUR|GBP|USD)=([0-9.,O]+)/g)) tr[m[1]] = cents(m[2]);
  const trRows = Number((/rows=(\d+)/.exec(trailer) || [])[1]);
  const control = {
    rows: rows.length, trailerRows: trRows, sums, trailer: tr,
    ok: rows.length === trRows && ['EUR', 'GBP', 'USD'].every(c => sums[c] === tr[c])
  };
  const latest = new Map();
  for (const r of rows) {
    const ref = String(r['Order Ref']).trim();
    const prev = latest.get(ref);
    if (!prev || stamp(r.UPDATED_AT) > stamp(prev.UPDATED_AT)) latest.set(ref, r);
  }
  const quarantine = [], candidates = [];
  for (const [ref, r] of latest) {
    const placed = realDate(r.Placed);
    if (!placed) { quarantine.push(ref); continue; }
    if (placed > CUTOVER) continue;
    const cur = curOf(r.Curr);
    const c = cents(r['Order Value']);
    const usd_cents = Math.floor((c * RATE[cur] + 5000) / 10000);
    candidates.push({ ref, note: String(r['Status Note']), placed, usd_cents });
  }
  candidates.sort((a, b) => (a.ref < b.ref ? -1 : a.ref > b.ref ? 1 : 0));
  quarantine.sort();
  return { candidates, quarantine, judgeRows: candidates.map(c => ({ ref: c.ref, note: c.note })), control };
}

