  if (sum !== answer.totals.usd_cents) problems.push('usd sum mismatch');
  const refs = answer.import.map(r => r.ref);
  if (new Set(refs).size !== refs.length) problems.push('duplicate import ref');
  if (new Set(answer.quarantine).size !== answer.quarantine.length) problems.push('duplicate quarantine ref');
  const known = new Set(prep.candidates.map(c => c.ref));
  for (const r of refs) if (!known.has(r)) problems.push('unknown ref ' + r);
  for (const r of answer.quarantine) if (known.has(r)) problems.push('quarantined ref also imported ' + r);
  if (!prep.control.ok) problems.push('control trailer mismatch: ' + JSON.stringify(prep.control));
  return problems.length ? { ok: false, problems } : true;
}

